INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Cyberkriminalität immer mit finanziellen Verlusten verbunden?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Datenverlust oder Rufschäden möglich"}, {"text": "Ja", "correct": false, "because": "Motive variieren"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolgt Cyberkriminalität oft?', 3, '[{"text": "Gewinnmaximierung", "correct": true, "because": "Häufig finanziell motiviert"}, {"text": "Hardware-Optimierung", "correct": false, "because": "Kein kriminelles Ziel"}, {"text": "Softwaretests", "correct": false, "because": "Nicht kriminell"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Arten von Cyberkriminalität gibt es?', 5, '[{"text": "Identitätsdiebstahl", "correct": true, "because": "Nutzung fremder Daten"}, {"text": "DDoS-Angriffe", "correct": true, "because": "Stört Dienste"}, {"text": "Datenkompression", "correct": false, "because": "Kein Verbrechen"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Cyberkriminalität nutzt oft Malware. b) Sie ist nur lokal relevant.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Global verbreitet"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Bekämpfung von Cyberkriminalität?', 4, '[{"text": "Sicherheitsupdates", "correct": false, "because": "Schließt Schwachstellen"}, {"text": "Mitarbeiterschulung", "correct": false, "because": "Reduziert Risiken"}, {"text": "Bildschirmdesign", "correct": true, "because": "Kein Sicherheitsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Cyberkriminalität nur Firmen betrifft?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Privatpersonen betroffen"}, {"text": "Ja", "correct": false, "because": "Breitere Reichweite"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Technik wird oft für Cyberkriminalität genutzt?', 3, '[{"text": "Phishing", "correct": true, "because": "Täuscht Nutzer"}, {"text": "SQL-Optimierung", "correct": false, "because": "Kein Angriff"}, {"text": "Grafikrendering", "correct": false, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Maßnahmen schützen vor Cyberkriminalität?', 5, '[{"text": "Firewalls", "correct": true, "because": "Blockiert Zugriffe"}, {"text": "Antivirus", "correct": true, "because": "Erkennt Malware"}, {"text": "Schnellere CPUs", "correct": false, "because": "Kein Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Cyberkriminalität ist global. b) Sie ist leicht zu stoppen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Schwer zu bekämpfen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht zur Abwehr von Cyberkriminalität?', 4, '[{"text": "Passwortrichtlinien", "correct": false, "because": "Erhöht Sicherheit"}, {"text": "Backups", "correct": false, "because": "Schützt Daten"}, {"text": "Neuer Monitor", "correct": true, "because": "Kein Sicherheitsvorteil"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist Cyberkriminalität nur digital?', 2, '[{"text": "Ja", "correct": true, "because": "Nutzt digitale Systeme"}, {"text": "Nein", "correct": false, "because": "Kern ist digital"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Folgen kann Cyberkriminalität haben?', 4, '[{"text": "Finanzielle Verluste", "correct": true, "because": "Direkte Schäden"}, {"text": "Datenverlust", "correct": true, "because": "Informationen gestohlen"}, {"text": "Schnellere Netzwerke", "correct": false, "because": "Kein Effekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Cyberkriminalität nur Hacker betrifft. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Opfer sind Nutzer"}, {"text": "Ja", "correct": false, "because": "Breitere Zielgruppe"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich zur Abwehr?', 3, '[{"text": "MFA", "correct": true, "because": "Erschwert Zugriff"}, {"text": "Schnelle Installation", "correct": false, "because": "Qualität zählt"}, {"text": "Geringe Kosten", "correct": false, "because": "Sicherheit wichtiger"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Cyberkriminalität nutzt Schwachstellen. b) Sie ist immer sichtbar.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Oft versteckt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Werkzeuge helfen gegen Cyberkriminalität?', 5, '[{"text": "IDS", "correct": true, "because": "Erkennt Angriffe"}, {"text": "VPN", "correct": true, "because": "Schützt Verbindungen"}, {"text": "Grafikeditor", "correct": false, "because": "Kein Schutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Prävention unwichtig?', 3, '[{"text": "Patch-Management", "correct": false, "because": "Schließt Lücken"}, {"text": "Überwachung", "correct": false, "because": "Erkennt Bedrohungen"}, {"text": "Bildschirmgröße", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann Cyberkriminalität physische Schäden verursachen?', 3, '[{"text": "Ja", "correct": true, "because": "Z. B. bei Infrastruktur"}, {"text": "Nein", "correct": false, "because": "Indirekt möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob Cyberkriminalität nur technisch ist?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Social Engineering"}, {"text": "Ja", "correct": false, "because": "Psychologische Aspekte"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Prävention?', 4, '[{"text": "Risikominimierung", "correct": true, "because": "Verhindert Schäden"}, {"text": "Kostensteigerung", "correct": false, "because": "Schutz spart langfristig"}, {"text": "Bandbreitenverbesserung", "correct": false, "because": "Kein Effekt"}]');
